const app=document.querySelector('#app'),dialog=document.querySelector('dialog'),fileInput=document.querySelector('#file-input');
const initial={name:'Your name',bio:'Books, films, and everything in between.\nA few of my favorite things.',avatar:'assets/avatar.png',collections:[{id:'books',title:'Books',slots:Array(9).fill(null)},{id:'films',title:'Films',slots:Array(9).fill(null)}]};
let state,db,draft,profileDraft,dirty=false,crop,uploadTarget,drag;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(message){const n=document.querySelector('#notice');n.textContent=message;n.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.style.display='none',3500)}
async function init(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('three-by-three',1);r.onupgradeneeded=()=>r.result.createObjectStore('profile');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});state=await new Promise((resolve,reject)=>{const r=db.transaction('profile').objectStore('profile').get('main');r.onsuccess=()=>resolve(r.result||structuredClone(initial));r.onerror=()=>reject(r.error)});render()}catch(e){state=structuredClone(initial);render();notify('Browser storage unavailable. Changes cannot be saved.')}}
async function persist(next){if(!db)throw Error('Storage unavailable');await new Promise((resolve,reject)=>{const tx=db.transaction('profile','readwrite');tx.objectStore('profile').put(next,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});state=next}
function tiles(slots,editable=false){return slots.map((slot,i)=>editable?`<button class="tile" data-slot="${i}" aria-label="${slot?'Edit':'Add'} image ${i+1}">${slot?`<img src="${esc(slot.preview)}" alt="Image ${i+1}"><span>${String(i+1).padStart(2,'0')}</span>`:'+'}</button>`:`<div class="tile ${slot?'':'empty'}">${slot?`<img src="${esc(slot.preview)}" alt="${esc(slot.alt||`Selection ${i+1}`)}">`:String(i+1).padStart(2,'0')}</div>`).join('')}
function render(){const route=location.hash||'#/';const editing=route==='#/edit';document.querySelector('#home-link').setAttribute('aria-current',route==='#/'?'page':'false');document.querySelector('#edit-link').setAttribute('aria-current',route!=='#/'?'page':'false');if(route.startsWith('#/collection/'))return renderEditor(decodeURIComponent(route.slice(13)));draft=null;dirty=false;profileDraft=structuredClone(state);document.title=`${state.name} — 3×3`;app.innerHTML=`<section class="profile" aria-label="Profile">${editing?`<button class="avatar-button" aria-label="Change profile picture"><img class="avatar" src="${esc(state.avatar)}" alt="Profile picture"></button><input class="name-input" aria-label="Username" maxlength="60" value="${esc(state.name)}"><textarea class="bio-input" aria-label="Biography" maxlength="600">${esc(state.bio)}</textarea><button class="profile-save">Save profile</button>`:`<img class="avatar" src="${esc(state.avatar)}" alt="Profile picture"><h1>${esc(state.name)}</h1><p class="bio">${esc(state.bio)}</p>`}</section><div class="collection-bar"><span>Collections / ${String(state.collections.length).padStart(2,'0')}</span><span>${editing?'Select a collection to edit':'Nine things, in no particular order.'}</span></div><section class="collections" aria-label="3 by 3 collections">${state.collections.map((c,i)=>`<${editing?'a':'article'} ${editing?`href="#/collection/${encodeURIComponent(c.id)}"`:''} class="collection ${editing?'editable':''}"><div class="grid">${tiles(c.slots)}</div><div class="collection-caption"><h2>${esc(c.title)}</h2><span>${String(i+1).padStart(2,'0')} / 3×3</span></div></${editing?'a':'article'}>`).join('')}${editing?'<a class="add-grid" href="#/collection/new" aria-label="Add a new 3 by 3"><b>+</b><span>Add a 3×3</span></a>':''}</section>`;if(editing){document.querySelector('.avatar-button').onclick=()=>pickImage('avatar');document.querySelector('.name-input').oninput=e=>{profileDraft.name=e.target.value;dirty=true};document.querySelector('.bio-input').oninput=e=>{profileDraft.bio=e.target.value;dirty=true};document.querySelector('.profile-save').onclick=saveProfile}}
async function saveProfile(){if(!profileDraft.name.trim())return notify('Enter a username.');try{await persist({...state,name:profileDraft.name.trim(),bio:profileDraft.bio,avatar:profileDraft.avatar});dirty=false;notify('Profile saved.')}catch{notify('Could not save. Your browser storage may be full.')}}
function renderEditor(id){const existing=state.collections.find(c=>c.id===id);if(id!=='new'&&!existing){location.hash='/edit';return}draft=structuredClone(existing||{id:crypto.randomUUID(),title:'',slots:Array(9).fill(null)});dirty=false;app.innerHTML=`<section class="editor"><a class="back" href="#/edit">← Back to profile</a><h1>${existing?'Edit 3×3':'New 3×3'}</h1><input class="title-input" aria-label="3 by 3 title" maxlength="80" placeholder="Title of your 3×3" value="${esc(draft.title)}"><div class="grid">${tiles(draft.slots,true)}</div><p class="hint">Click a square to add or adjust an image.</p><div class="editor-actions"><button class="primary" id="save-grid">Save 3×3</button><a class="back" style="padding:12px" href="#/edit">Cancel</a></div><p class="save-error" role="alert"></p></section>`;document.querySelector('.title-input').oninput=e=>{draft.title=e.target.value;dirty=true};bindSlots();document.querySelector('#save-grid').onclick=async()=>{if(!draft.title.trim()){document.querySelector('.save-error').textContent='Give your 3×3 a title.';document.querySelector('.title-input').focus();return}const next=structuredClone(state);draft.title=draft.title.trim();const index=next.collections.findIndex(c=>c.id===draft.id);if(index<0)next.collections.push(draft);else next.collections[index]=draft;try{await persist(next);dirty=false;location.hash='/';notify('3×3 saved.')}catch{document.querySelector('.save-error').textContent='Could not save. Browser storage may be full. Your edits are still here.'}}}
function bindSlots(){document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{const i=+b.dataset.slot;uploadTarget=i;if(draft.slots[i])openCrop(draft.slots[i]);else pickImage(i)})}
function pickImage(target){uploadTarget=target;fileInput.value='';fileInput.click()}
fileInput.onchange=async()=>{const file=fileInput.files[0];if(!file)return;if(!file.type.startsWith('image/'))return notify('Choose an image file.');if(file.size>30*1024*1024)return notify('Choose an image smaller than 30 MB.');try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const im=await loadImage(src);const canvas=document.createElement('canvas');const scale=Math.min(1,1800/Math.max(im.width,im.height));canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);openCrop({source:canvas.toDataURL('image/jpeg',.9),zoom:1,x:0,y:0,alt:file.name.replace(/\.[^.]+$/,'')})}catch{notify('This image could not be opened. Try PNG, JPEG, or WebP.')}};
function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src})}
async function openCrop(slot){try{const im=await loadImage(slot.source);crop={...slot,im};document.querySelector('#crop-image').src=slot.source;document.querySelector('#zoom').value=crop.zoom;document.querySelector('#crop-error').textContent='';if(!dialog.open)dialog.showModal();paintCrop()}catch{notify('Image could not be loaded.')}}
function paintCrop(){const s=document.querySelector('#crop-stage').clientWidth;const scale=Math.max(s/crop.im.width,s/crop.im.height)*crop.zoom;const img=document.querySelector('#crop-image');img.style.width=crop.im.width*scale+'px';img.style.height=crop.im.height*scale+'px';img.style.left=(s-crop.im.width*scale)/2+crop.x*s+'px';img.style.top=(s-crop.im.height*scale)/2+crop.y*s+'px';document.querySelector('#zoom-value').value=Math.round(crop.zoom*100)+'%'}
document.querySelector('#zoom').oninput=e=>{crop.zoom=+e.target.value;paintCrop()};document.querySelector('#reset-crop').onclick=()=>{crop.zoom=1;crop.x=crop.y=0;document.querySelector('#zoom').value=1;paintCrop()};document.querySelector('#replace-image').onclick=()=>pickImage(uploadTarget);
const stage=document.querySelector('#crop-stage');stage.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,cx:crop.x,cy:crop.y};stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(!drag)return;crop.x=drag.cx+(e.clientX-drag.x)/stage.clientWidth;crop.y=drag.cy+(e.clientY-drag.y)/stage.clientWidth;paintCrop()};stage.onpointerup=stage.onpointercancel=()=>drag=null;stage.onkeydown=e=>{const directions={ArrowLeft:[-.01,0],ArrowRight:[.01,0],ArrowUp:[0,-.01],ArrowDown:[0,.01]};if(directions[e.key]){e.preventDefault();crop.x+=directions[e.key][0];crop.y+=directions[e.key][1];paintCrop()}};window.addEventListener('resize',()=>{if(dialog.open&&crop)paintCrop()});
document.querySelector('#apply-crop').onclick=()=>{const c=document.createElement('canvas');c.width=c.height=600;const ctx=c.getContext('2d');ctx.fillStyle='#080808';ctx.fillRect(0,0,600,600);const scale=Math.max(600/crop.im.width,600/crop.im.height)*crop.zoom;ctx.drawImage(crop.im,(600-crop.im.width*scale)/2+crop.x*600,(600-crop.im.height*scale)/2+crop.y*600,crop.im.width*scale,crop.im.height*scale);const {im,...saved}=crop;saved.preview=c.toDataURL('image/jpeg',.9);if(uploadTarget==='avatar'){profileDraft.avatar=saved.preview;document.querySelector('.avatar').src=saved.preview}else{draft.slots[uploadTarget]=saved;document.querySelector('.editor .grid').innerHTML=tiles(draft.slots,true);bindSlots()}dirty=true;dialog.close()};
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(a&&dirty&&!confirm('Discard unsaved changes?'))e.preventDefault()});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});window.addEventListener('hashchange',render);init();
